update_rule.pseudocode:
if t == 0:
  if network_type == 'small_world':
    G <- WattsStrogatz(N=population_size, k=round(avg_degree), p=rewiring_prob_ws)
  else if network_type == 'scale_free':
    G <- BarabasiAlbert(N=population_size, m=preferential_attachment_m)
  else:
    G <- ErdosRenyi(N=population_size, p=avg_degree/(population_size-1))
  # Homophily post-processing
  for each edge (i,j) in G:
    if rand() < homophily_by_attitude and |att_i - att_j| > 0.3:
      attempt to rewire j to a node j' with closer attitude
  update Person.degree, Person.centrality (eigenvector or degree normalized)
else:
  # Daily rewiring
  num_rewire <- Binomial(|E|, rewiring_rate_daily)
  repeat num_rewire times:
    pick random edge (i,j), remove it
    pick node i, connect to node j' sampled with prob proportional to (1 - |att_i - att_j'|) if homophily>0 else uniform
  update Person.degree, Person.centrality (incremental if available)
